(function () {
  var S = window.CardSets && window.CardSets.get('wild-mammals');
  if (!S) return;
  var extra = [{"name":"Linnaeus's Two-toed Sloth","rarity":"rare","id":"linnaeuss-two-toed-sloth","subtitle":"Oddball","details":"Linnaeus's two-toed sloth is a surprisingly strong swimmer, paddling through flooded Amazon forest with its long arms during the rainy season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cholepus_didactylus_-_Flickr_-_Dick_Culbert.jpg?width=1024"},{"name":"Black Flying Fox","rarity":"rare","id":"black-flying-fox","subtitle":"Bat","details":"A large dark fruit bat of northern Australia and New Guinea that gathers in mangrove camps and feeds on eucalypt blossom, fruit and nectar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_Flying_Fox_-_Pteropus_alecto_-_%28IMG_4883%29.jpg?width=800"},{"name":"Little Red Flying Fox","rarity":"rare","id":"little-red-flying-fox","subtitle":"Bat","details":"A nomadic Australian fruit bat with reddish fur that follows flowering eucalypts across the outback, roosting in camps of thousands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Little_red_flying_fox_2016.png?width=500"},{"name":"Madagascan Flying Fox","rarity":"rare","id":"madagascan-flying-fox","subtitle":"Bat","details":"Madagascar's largest bat, a rusty-red fruit eater that roosts in exposed treetops and travels far each night between feeding and roosting trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteropus_rufus_ii.jpg?width=1024"},{"name":"Livingstone's Fruit Bat","rarity":"rare","id":"livingstones-fruit-bat","subtitle":"Bat","details":"A large fruit bat found only in the Comoros islands, where it roosts in mountain forest trees and feeds on fruit, nectar and leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bristol.zoo.livfruitbat.arp.jpg?width=1024"},{"name":"Spectral Bat","rarity":"rare","id":"spectral-bat","subtitle":"Bat","details":"The largest carnivorous bat in the Americas, it hunts birds, rodents and other bats, roosting in hollow trees in Central and South America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spectral_bat_photo.jpg?width=1024"},{"name":"Ghost Bat","rarity":"rare","id":"ghost-bat","subtitle":"Bat","details":"Australia's only carnivorous bat, a pale, long-eared hunter that swoops from cave roosts to take birds, lizards and small mammals at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281%29Ghost_Bat_078.jpg?width=1024"},{"name":"Greater Horseshoe Bat","rarity":"rare","id":"greater-horseshoe-bat","subtitle":"Bat","details":"A European bat named for its horseshoe-shaped noseleaf, which focuses its echolocation as it hunts beetles and moths over pastures and woods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Greater_horseshoe_bat_%28Rhinolophus_ferrumequinum%29_Hrdovicka.jpg?width=1024"},{"name":"Honduran White Bat","rarity":"rare","id":"honduran-white-bat","subtitle":"Bat","details":"A tiny snow-white bat of Central America that cuts large leaves into tent roosts, where its white fur turns greenish in the filtered light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ectophylla_alba_Costa_Rica.jpg?width=1024"},{"name":"Red Fox","rarity":"uncommon","id":"red-fox","subtitle":"Carnivore","details":"The red fox, the world's most widespread carnivore, hunts rodents by listening through snow and pouncing from above.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portrait_of_a_red_fox_in_Rautas_fj%C3%A4llurskog_%28cropped%29.jpg?width=1024"},{"name":"Arctic Fox","rarity":"uncommon","id":"arctic-fox","subtitle":"Carnivore","details":"The Arctic fox changes from brown summer fur to white winter camouflage and survives temperatures far below freezing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_lagopus_in_Iceland_%28cropped_3%29.jpg?width=1024"},{"name":"Fennec Fox","rarity":"uncommon","id":"fennec-fox","subtitle":"Carnivore","details":"The fennec fox, the smallest canid, uses its enormous ears to shed heat and hear prey in Sahara desert sands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fennec_Fox_Vulpes_zerda.jpg?width=1024"},{"name":"Gray Fox","rarity":"uncommon","id":"gray-fox","subtitle":"Carnivore","details":"The gray fox of North and Central America can climb trees using hooked claws, denning in hollow trunks and high branches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray_fox.jpg?width=1024"},{"name":"Kit Fox","rarity":"uncommon","id":"kit-fox","subtitle":"Carnivore","details":"The kit fox is a small, large-eared desert fox of the American Southwest and Mexico that shelters in burrows by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_macrotis_mutica_sitting.jpg?width=1024"},{"name":"Swift Fox","rarity":"uncommon","id":"swift-fox","subtitle":"Carnivore","details":"The swift fox is a cat-sized prairie fox of the Great Plains, named for its speed when crossing open grassland at dusk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Swift_Fox_Colorado_Wolf_and_Wildlife_cropped.jpg?width=1024"},{"name":"Crab-eating Fox","rarity":"uncommon","id":"crab-eating-fox","subtitle":"Carnivore","details":"The crab-eating fox forages along South American forest edges and wetlands, feasting on crabs in the wet season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crab-eating_Fox_%28cropped%29.JPG?width=1024"},{"name":"Raccoon","rarity":"uncommon","id":"raccoon","subtitle":"Carnivore","details":"The raccoon's nimble, sensitive forepaws help it feel for food along North American streams, often seeming to wash it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raccoon_in_Central_Park_%2835264%29.jpg?width=1024"},{"name":"Kinkajou","rarity":"uncommon","id":"kinkajou","subtitle":"Carnivore","details":"The kinkajou is a honey-loving, tree-dwelling procyonid of Central and South American rainforests with a prehensile tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Potos_flavus_%288973438737%29.jpg?width=1024"},{"name":"Striped Skunk","rarity":"uncommon","id":"striped-skunk","subtitle":"Carnivore","details":"The striped skunk warns predators with bold white stripes before spraying a potent musk from glands under its tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skunk_about_to_spray.jpg?width=1024"},{"name":"American Mink","rarity":"uncommon","id":"american-mink","subtitle":"Carnivore","details":"The American mink is a semi-aquatic mustelid that dives for crayfish and fish along North American waterways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MinkforWiki.jpg?width=1024"},{"name":"Ermine","rarity":"uncommon","id":"ermine","subtitle":"Carnivore","details":"The ermine, or stoat, turns white in winter except for its black tail tip, the prized fur long used on royal robes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%B8yskatt_%28Mustela_erminea_erminea%29%2C_Lista%2C_Norway.jpg?width=1024"},{"name":"Long-tailed Weasel","rarity":"uncommon","id":"long-tailed-weasel","subtitle":"Carnivore","details":"The long-tailed weasel is a fierce North American hunter that takes prey larger than itself, turning white in northern winters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long-tailed_Weasel%2C_Sonoma_County%2C_US-CA%2C_US_imported_from_iNaturalist_photo_108909271.jpg?width=1024"},{"name":"Black-footed Ferret","rarity":"uncommon","id":"black-footed-ferret","subtitle":"Carnivore","details":"The black-footed ferret hunts prairie dogs in their own burrows on the Great Plains, sleeping underground by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mustela_nigripes_2.jpg?width=1024"},{"name":"European Polecat","rarity":"uncommon","id":"european-polecat","subtitle":"Carnivore","details":"The European polecat, ancestor of the domestic ferret, hunts frogs, rodents and rabbits in wetlands, woods and farmland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Storm_the_polecat.jpg?width=1024"},{"name":"Sable","rarity":"uncommon","id":"sable","subtitle":"Carnivore","details":"The sable is a dark-furred marten of Siberian taiga forests, long prized for its exceptionally soft, dense coat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sobol_bur.jpg?width=1024"},{"name":"American Marten","rarity":"uncommon","id":"american-marten","subtitle":"Carnivore","details":"The American marten hunts squirrels and voles through North America's conifer forests, climbing trees with ease.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Newfoundland_Pine_Marten.jpg?width=1024"},{"name":"Yellow-throated Marten","rarity":"uncommon","id":"yellow-throated-marten","subtitle":"Carnivore","details":"The yellow-throated marten is a large, boldly colored Asian marten that hunts in pairs, even taking small deer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Martes_flavigula%2C_yellow-throated_marten.jpg?width=1024"},{"name":"Asian Small-clawed Otter","rarity":"uncommon","id":"asian-small-clawed-otter","subtitle":"Carnivore","details":"The Asian small-clawed otter, the smallest otter, feels for crabs under stones with sensitive, nearly clawless fingers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Otter_-_melbourne_zoo.jpg?width=1024"},{"name":"Neotropical Otter","rarity":"uncommon","id":"neotropical-otter","subtitle":"Carnivore","details":"The neotropical otter is a shy, solitary river otter found from Mexico to Argentina along forested waterways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lontra_longicaudis_4.jpeg?width=1024"},{"name":"Spotted-necked Otter","rarity":"uncommon","id":"spotted-necked-otter","subtitle":"Carnivore","details":"The spotted-necked otter swims in clear African lakes and rivers, catching fish and crabs with its webbed paws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spotted-necked_otter_1.jpg?width=1024"},{"name":"White-nosed Coati","rarity":"uncommon","id":"white-nosed-coati","subtitle":"Carnivore","details":"The white-nosed coati forages in troops through southwestern US and Mexican forests, its long snout probing for insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/194%20White-nosed%20coati%20at%20the%20beach%20in%20Yucat%C3%A1n%20Photo%20by%20Giles%20Laurent.jpg?width=1024"},{"name":"South American Coati","rarity":"uncommon","id":"south-american-coati","subtitle":"Carnivore","details":"South American coati bands forage noisily in trees and leaf litter, tails held high like flags above the undergrowth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nasenbaer_Nasua_nasua_Zoo_Augsburg-04.jpg?width=1024"},{"name":"Ringtail","rarity":"uncommon","id":"ringtail","subtitle":"Carnivore","details":"The ringtail, a raccoon relative of the American Southwest, squeezes through rocky canyons with its long banded tail for balance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Squaw-ringtail-28073.jpg?width=1024"},{"name":"Common Genet","rarity":"uncommon","id":"common-genet","subtitle":"Carnivore","details":"The common genet is a spotted, cat-like viverrid of Africa and southern Europe that hunts rodents and birds at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Genetta_genetta_felina_%28Wroclaw_zoo%29.JPG?width=1024"},{"name":"Asian Palm Civet","rarity":"uncommon","id":"asian-palm-civet","subtitle":"Carnivore","details":"The Asian palm civet climbs palm trees across Asia and is known for eating ripe coffee cherries in plantations and gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common_Palm_Civet_%28Paradoxurus_hermaphroditus%29_%287781509830%29.jpg?width=1024"},{"name":"Banded Mongoose","rarity":"uncommon","id":"banded-mongoose","subtitle":"Carnivore","details":"Banded mongooses live in cooperative African groups, foraging together for insects and taking turns babysitting the pups.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banded_Mongoose_Nose_Detail%2C_crop.jpg?width=1024"},{"name":"Egyptian Mongoose","rarity":"uncommon","id":"egyptian-mongoose","subtitle":"Carnivore","details":"The Egyptian mongoose, the ancient ichneumon, hunts snakes and rodents in wetlands and scrub around the Mediterranean and Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herpestes_ichneumon_%D0%95%D0%B3%D0%B8%D0%BF%D0%B5%D1%82%D1%81%D0%BA%D0%B8%D0%B9_%D0%BC%D0%B0%D0%BD%D0%B3%D1%83%D1%81%D1%82%2C_%D0%B8%D0%BB%D0%B8_%D1%84%D0%B0%D1%80%D0%B0%D0%BE%D0%BD%D0%BE%D0%B2%D0%B0_%D0%BA%D1%80%D1%8B%D1%81%D0%B0%2C_%D0%B8%D0%BB%D0%B8_%D0%B8%D1%85%D0%BD%D0%B5%D0%B2%D0%BC%D0%BE%CC%81%D0%BD.jpg?width=1024"},{"name":"Rhesus Macaque","rarity":"uncommon","id":"rhesus-macaque","subtitle":"Primate","details":"From Afghanistan to China, the adaptable rhesus macaque thrives in mountains, grasslands, villages and temple towns alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhesus_macaque_%28Macaca_mulatta_mulatta%29%2C_male%2C_Gokarna.jpg?width=1024"},{"name":"Crab-eating Macaque","rarity":"uncommon","id":"crab-eating-macaque","subtitle":"Primate","details":"Also called the long-tailed macaque, this Southeast Asian monkey swims confidently and forages along rivers, coasts and mangroves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ubud_Monkey_Family.jpg?width=1024"},{"name":"Vervet Monkey","rarity":"uncommon","id":"vervet-monkey","subtitle":"Primate","details":"African vervets use distinct alarm calls for leopards, eagles and snakes, and youngsters learn which call means which danger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cercopiteco_verde_%28Chlorocebus_pygerythrus%29%2C_parque_nacional_del_lago_Nakuru%2C_Kenia%2C_2024-05-18%2C_DD_77.jpg?width=1024"},{"name":"Patas Monkey","rarity":"uncommon","id":"patas-monkey","subtitle":"Primate","details":"The world's fastest primate, the long-limbed patas of African savannas can sprint at 55 km/h and stands tall to scan for danger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Patas_Monkey.jpg?width=1024"},{"name":"Dusky Leaf Monkey","rarity":"uncommon","id":"dusky-leaf-monkey","subtitle":"Primate","details":"Malaya and Thailand's spectacled langur is born bright orange, darkening to grey with bold white eye-rings as it grows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trachypithecus%20obscurus%20-%20Kaeng%20Krachan.jpg?width=1024"},{"name":"Hanuman Langur","rarity":"uncommon","id":"hanuman-langur","subtitle":"Primate","details":"Named for the Hindu monkey god Hanuman, this long-tailed Indian langur leaps boldly across rooftops, temples and forest trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Northern_plains_gray_langur.jpg?width=1024"},{"name":"Tufted Capuchin","rarity":"uncommon","id":"tufted-capuchin","subtitle":"Primate","details":"South America's sturdy tufted capuchin cracks palm nuts with stones and is among the most inventive tool-users of any monkey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tufted_capuchin_on_a_branch_in_Singapore.jpg?width=1024"},{"name":"White-faced Capuchin","rarity":"uncommon","id":"white-faced-capuchin","subtitle":"Primate","details":"Central America's white-faced capuchin rubs itself with plants as insect repellent and forages cleverly from canopy to forest floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panamanian_white-faced_capuchins_%2881622%292.jpg?width=1024"},{"name":"Common Squirrel Monkey","rarity":"uncommon","id":"common-squirrel-monkey","subtitle":"Primate","details":"Amazon troops of fifty or more squirrel monkeys bounce through river forest, hunting insects among the branches all day long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mono_ardilla_-_Saimiri_sciureus.jpg?width=1024"},{"name":"Common Marmoset","rarity":"uncommon","id":"common-marmoset","subtitle":"Primate","details":"Brazil's white-tufted marmoset gnaws tree bark to sip flowing gum, living in family groups where older siblings help raise the young.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wei%C3%9Fb%C3%BCschelaffe_%28Callithrix_jacchus%29.jpg?width=1024"},{"name":"Pygmy Marmoset","rarity":"uncommon","id":"pygmy-marmoset","subtitle":"Primate","details":"The world's smallest monkey weighs little more than an apple and clings to Amazon tree trunks, feeding on gum and tiny insects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dv%C3%A6rgsilkeabe_Callithrix_pygmaea.jpg?width=1024"},{"name":"Verreaux's Sifaka","rarity":"uncommon","id":"verreauxs-sifaka","subtitle":"Primate","details":"Madagascar's dancing lemur bounds sideways across open ground on two legs, arms raised, between the spiny forests of the south.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Verreauxs_Sifika_Kirindy_Madagascar.jpg?width=1024"},{"name":"Red Ruffed Lemur","rarity":"uncommon","id":"red-ruffed-lemur","subtitle":"Primate","details":"One of Madagascar's largest lemurs, the red ruffed kind builds leafy nests for its litters high in the eastern rainforest canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red_ruffed_lemur_%28Varecia_rubra%29.jpg?width=1024"},{"name":"Black-and-white Ruffed Lemur","rarity":"uncommon","id":"black-and-white-ruffed-lemur","subtitle":"Primate","details":"Boldly pied and loud-voiced, this big Madagascan lemur hangs upside down to reach fruit and is an important pollinator of travellers' palms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_black_and_white_ruffed_lemur.jpg?width=1024"},{"name":"Bengal Slow Loris","rarity":"uncommon","id":"bengal-slow-loris","subtitle":"Primate","details":"South Asia's slow loris moves hand over hand at night, and carries a rare defence for a primate: a venomous bite from its elbow glands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Captive_N._bengalensis_from_Laos_with_6-week_baby.JPG?width=1024"},{"name":"Philippine Tarsier","rarity":"uncommon","id":"philippine-tarsier","subtitle":"Primate","details":"Bohol's tiny tarsier turns its head almost full circle and leaps three metres between trees, hunting insects by huge-eyed night vision.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philippine_tarsier_%28Carlito_syrichta_fraterculus%29_Bohol.jpg?width=1024"},{"name":"Senegal Bushbaby","rarity":"uncommon","id":"senegal-bushbaby","subtitle":"Primate","details":"Africa's lesser galago springs two metres between acacia branches at night, marking its routes with urine-washed hands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Galago_senegalensis.jpg?width=1024"},{"name":"White-tailed Deer","rarity":"uncommon","id":"white-tailed-deer","subtitle":"Hoofed Mammal","details":"Named for the white underside of its tail, raised like a flag when alarmed, this adaptable deer thrives from Canadian forests to Peru.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White-tailed_deer.jpg?width=1024"},{"name":"Elk","rarity":"uncommon","id":"elk","subtitle":"Hoofed Mammal","details":"A bull elk's autumn bugle can carry for kilometres across mountain valleys; elk are among the largest deer, second in North America only to moose.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jasper.Wapiti-Hirsch.P1033401.jpg?width=1024"},{"name":"Red Deer","rarity":"uncommon","id":"red-deer","subtitle":"Hoofed Mammal","details":"One of the world's largest deer, red deer stags roar through the autumn rut and can grow antlers over a metre across in a single summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cervus_elaphus_Luc_Viatour_6.jpg?width=1024"},{"name":"Reindeer","rarity":"uncommon","id":"reindeer","subtitle":"Hoofed Mammal","details":"Uniquely among deer, both male and female reindeer grow antlers; herds migrate across Arctic tundra in some of the longest land journeys on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reinbukken_p%C3%A5_frisk_gr%C3%B8nt_beite._-_panoramio.jpg?width=1024"},{"name":"Fallow Deer","rarity":"uncommon","id":"fallow-deer","subtitle":"Hoofed Mammal","details":"Introduced across much of the world from the Mediterranean, fallow deer bucks grow broad, shovel-shaped antlers and come in many colour forms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%BClmen%2C_Wildpark_--_2018_--_3762.jpg?width=1024"},{"name":"Chital","rarity":"uncommon","id":"chital","subtitle":"Hoofed Mammal","details":"The spotted deer of Indian forests keeps its white spots for life and often feeds beneath langur monkeys, sharing dropped fruit and alarm calls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/066_Chital_in_Ranthambore_National_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Common Warthog","rarity":"uncommon","id":"common-warthog","subtitle":"Hoofed Mammal","details":"A warthog kneels on padded wrists to graze and backs into its burrow so its big curved tusks face outward against any predator that follows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_warthog_%28Phacochoerus_africanus_sundevallii%29_male.jpg?width=1024"},{"name":"Wild Boar","rarity":"uncommon","id":"wild-boar","subtitle":"Hoofed Mammal","details":"Ancestor of the domestic pig, the wild boar is a powerful, adaptable forager found from European oakwoods to Asian jungle, rooting up soil for food.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wildschwein%2C_N%C3%A4he_Pulverstampftor_%28cropped%29.jpg?width=1024"},{"name":"Red River Hog","rarity":"uncommon","id":"red-river-hog","subtitle":"Hoofed Mammal","details":"The most colourful pig in Africa, this red-coated, white-striped hog of Congo forests roots through leaf litter in family groups called sounders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pinselohrschwein_Potamochoerus_porcus_Tierpark_Hellabrunn-5.jpg?width=1024"},{"name":"Babirusa","rarity":"uncommon","id":"babirusa","subtitle":"Hoofed Mammal","details":"A wild pig of Sulawesi whose name means 'pig-deer': the boar's upper tusks grow up through its snout and curve back toward its forehead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hirscheber1a.jpg?width=1024"},{"name":"Collared Peccary","rarity":"uncommon","id":"collared-peccary","subtitle":"Hoofed Mammal","details":"Also called the javelina, this pig-like mammal of American deserts and forests travels in herds, marked by a pale collar around its neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pecari_tajacu_-_02.jpg?width=1024"},{"name":"Guanaco","rarity":"uncommon","id":"guanaco","subtitle":"Hoofed Mammal","details":"A wild camel cousin of the high Andes, the guanaco survives on sparse desert grassland and is the ancestor from which llamas were domesticated.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guanaco_%28Lama_guanicoe%29_Leona_Amarga.jpg?width=1024"},{"name":"Vicuña","rarity":"uncommon","id":"vicu-a","subtitle":"Hoofed Mammal","details":"The vicuña's fleece is among the finest natural fibres in the world; this small, graceful camel relative grazes only in high Andean grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vicuna_%2889163948%29_%28cropped%29.jpg?width=1024"},{"name":"Springbok","rarity":"uncommon","id":"springbok","subtitle":"Hoofed Mammal","details":"South Africa's national animal is famous for 'pronking' — bouncing high on stiff legs — and once migrated across the Karoo in vast herds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/174_Male_Springbok_in_Etosha_National_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Impala","rarity":"uncommon","id":"impala","subtitle":"Hoofed Mammal","details":"Among the most graceful of antelope, an impala can leap three metres high and ten metres long, flashing black stripes on its hindquarters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common_impala_%28Aepyceros_melampus_melampus%29_male_Serengeti.jpg?width=1024"},{"name":"Thomson's Gazelle","rarity":"uncommon","id":"thomsons-gazelle","subtitle":"Hoofed Mammal","details":"A small, swift gazelle of the Serengeti, the 'tommie' bounds away from danger in stiff-legged hops and grazes in herds of thousands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gacela_de_Thomson_%28Eudorcas_thomsonii%29%2C_parque_nacional_de_Amboseli%2C_Kenia%2C_2024-05-23%2C_DD_11.jpg?width=1024"},{"name":"Blue Wildebeest","rarity":"uncommon","id":"blue-wildebeest","subtitle":"Hoofed Mammal","details":"Famed for the great Serengeti migration, blue wildebeest travel in herds over a million strong, following the rains in a year-long circuit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue_Wildebeest%2C_Ngorongoro.jpg?width=1024"},{"name":"Waterbuck","rarity":"uncommon","id":"waterbuck","subtitle":"Hoofed Mammal","details":"A shaggy antelope never far from water, the waterbuck's greasy, musky coat is said to taint its meat, and rams wear bold white ring markings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/069_Waterbuck_at_Queen_Elizabeth_National_Park_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Roan Antelope","rarity":"uncommon","id":"roan-antelope","subtitle":"Hoofed Mammal","details":"One of Africa's largest antelope, the roan has a striking black-and-white face mask and curved horns, and will charge predators that threaten calves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roan_antelope_%28Hippotragus_equinus_equinus%29_Mlilwane.jpg?width=1024"},{"name":"Addax","rarity":"uncommon","id":"addax","subtitle":"Hoofed Mammal","details":"A pale antelope of the deep Sahara, the addax may never need to drink free water, surviving on moisture from the desert plants it eats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_big_male_Addax_showing_as_the_power_of_his_horns.jpg?width=1024"},{"name":"Scimitar-horned Oryx","rarity":"uncommon","id":"scimitar-horned-oryx","subtitle":"Hoofed Mammal","details":"Named for horns that curve like scimitars, this oryx once roamed the whole Sahara fringe and can raise its body temperature to save water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oryx_Dammah.jpg?width=1024"},{"name":"Nilgai","rarity":"uncommon","id":"nilgai","subtitle":"Hoofed Mammal","details":"Asia's largest antelope, the nilgai or 'blue bull' of India is slate-grey in males, with short conical horns and a beard of coarse hair.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nilgai_%28Boselaphus_tragocamelus%29_male.jpg?width=1024"},{"name":"Blackbuck","rarity":"uncommon","id":"blackbuck","subtitle":"Hoofed Mammal","details":"A male blackbuck's dark coat and corkscrew horns contrast sharply with white markings; this swift Indian antelope can outrun most predators.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blackbuck_male_female.jpg?width=1024"},{"name":"Mountain Goat","rarity":"uncommon","id":"mountain-goat","subtitle":"Hoofed Mammal","details":"Not a true goat but a goat-antelope, this shaggy white climber of North American crags has rubbery hoof pads for gripping icy rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mountain_Goat%2C_Enchantments_Basin.jpg?width=1024"},{"name":"Chamois","rarity":"uncommon","id":"chamois","subtitle":"Hoofed Mammal","details":"An agile goat-antelope of European mountains, the chamois can leap six metres and run at 50 kilometres an hour across steep alpine slopes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/064_Wild_Chamois_Parc_r%C3%A9gional_Chasseral_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Takin","rarity":"uncommon","id":"takin","subtitle":"Hoofed Mammal","details":"A hefty goat-antelope of Himalayan bamboo forests, the takin looks part goat, part gnu, and migrates up and down mountains with the seasons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thimphu-Takin-Reservat-06-2015-gje.jpg?width=1024"},{"name":"Przewalski's Horse","rarity":"uncommon","id":"przewalskis-horse","subtitle":"Hoofed Mammal","details":"The world's last truly wild horse, never domesticated, this stocky horse of the Mongolian steppe was reintroduced from zoo herds to its homeland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Przewalskis_horse_02.jpg?width=1024"},{"name":"Yellow-bellied Marmot","rarity":"uncommon","id":"yellow-bellied-marmot","subtitle":"Rodent","details":"A chunky ground squirrel of western North American mountains, nicknamed the whistle pig for its piercing alarm call.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marmota_flaviventris_%28Yellow_Bellied_Marmot%29%2C_Yosemite_NP_-_Diliff.jpg?width=1024"},{"name":"Eastern Chipmunk","rarity":"uncommon","id":"eastern-chipmunk","subtitle":"Rodent","details":"This striped North American ground squirrel stuffs its elastic cheek pouches with seeds to stock a burrow larder for winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chipmunk_with_stuffed_cheeks_in_Prospect_Park_%2805980%29.jpg?width=1024"},{"name":"Thirteen-lined Ground Squirrel","rarity":"uncommon","id":"thirteen-lined-ground-squirrel","subtitle":"Rodent","details":"Striped and dotted from nose to tail, this prairie squirrel hibernates so deeply its heart rate drops to a few beats a minute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thirteen-lined_ground_squirrel.jpg?width=1024"},{"name":"Golden-mantled Ground Squirrel","rarity":"uncommon","id":"golden-mantled-ground-squirrel","subtitle":"Rodent","details":"Resembling a large chipmunk but lacking face stripes, this western squirrel fattens on seeds before a long winter hibernation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rocky_Mountain_golden-mantled_ground_squirrel_%28Callospermophilus_lateralis_tescorum%29_Hwy_93_2.jpg?width=1024"},{"name":"Northern Flying Squirrel","rarity":"uncommon","id":"northern-flying-squirrel","subtitle":"Rodent","details":"A soft-furred glider of northern conifer forests, it feeds heavily on truffles and lichens and nests in tree cavities.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Northern_Flying_Squirrel%2C_D%27Alembert%2C_6400_Route_d%27Aiguebelle%2C_Rouyn-Noranda%2C_QC%2C_Canada_imported_from_iNaturalist_photo_41110662.jpg?width=1024"},{"name":"Siberian Flying Squirrel","rarity":"uncommon","id":"siberian-flying-squirrel","subtitle":"Rodent","details":"This big-eyed glider of old Eurasian forests sails between trees on skin membranes and raises young in woodpecker holes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteromys_volans_292232567.jpg?width=1024"},{"name":"American Red Squirrel","rarity":"uncommon","id":"american-red-squirrel","subtitle":"Rodent","details":"A feisty, territorial tree squirrel that defends cone middens in North American conifer forests and chatters at intruders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Richardson%27s_red_squirrel_%28Tamiasciurus_hudsonicus_richardsoni%29_Moraine_Lake.jpg?width=1024"},{"name":"Eastern Cottontail","rarity":"uncommon","id":"eastern-cottontail","subtitle":"Small Mammal","details":"A North American rabbit of meadows and brush, it freezes to stay hidden, then bursts away in a zigzag when danger nears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern_cottontail_%28Sylvilagus_floridanus%29_foraging_on_ground_vegetation.jpg?width=1024"},{"name":"European Rabbit","rarity":"uncommon","id":"european-rabbit","subtitle":"Small Mammal","details":"The ancestor of domestic rabbits, this social burrower digs branching warrens and thumps a hind foot to warn of danger.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oryctolagus_cuniculus_-_euqirneto_-_419737670_%28cropped%29.jpeg?width=1024"},{"name":"European Hare","rarity":"uncommon","id":"european-hare","subtitle":"Small Mammal","details":"Larger and longer-eared than a rabbit, this hare shelters in a shallow ground hollow and can sprint at 70 kilometres an hour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European_hare_%28_Lepus_europaeus%29.jpg?width=1024"},{"name":"Arctic Hare","rarity":"uncommon","id":"arctic-hare","subtitle":"Small Mammal","details":"Built for the far north, this large hare turns white in winter, digs through snow for willow twigs, and huddles for warmth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arctic_Hare_1.jpg?width=1024"},{"name":"American Pika","rarity":"uncommon","id":"american-pika","subtitle":"Small Mammal","details":"This tiny, round-eared rabbit relative spends summer gathering haypiles of wildflowers to survive alpine winters awake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ochotona_princeps_rockies.JPG?width=1024"},{"name":"Plains Viscacha","rarity":"uncommon","id":"plains-viscacha","subtitle":"Rodent","details":"A burrowing rodent of the Argentine pampas whose colonies dig sprawling tunnel towns and pile odd objects at entrances.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lagostomus_maximus%2C_Plains_Viscacha.jpg?width=1024"},{"name":"Degu","rarity":"uncommon","id":"degu","subtitle":"Rodent","details":"A social Chilean rodent with a tufted tail, the degu communicates in a rich vocabulary of chirps, squeaks and foot-stomps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Octodon_degus_-Heidelberg_Zoo%2C_Germany-8a.jpg?width=1024"},{"name":"Naked Mole-rat","rarity":"uncommon","id":"naked-mole-rat","subtitle":"Rodent","details":"Nearly hairless and almost blind, this East African burrower lives in ant-like colonies ruled by a single breeding queen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Webs180130-rat.jpg?width=1024"},{"name":"Gambian Pouched Rat","rarity":"uncommon","id":"gambian-pouched-rat","subtitle":"Rodent","details":"One of Africa's largest rats, this species carries food in hamster-like cheek pouches and has an exceptional sense of smell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cricetomys_gambianus_as_a_captive_pet.jpg?width=1024"},{"name":"Merriam's Kangaroo Rat","rarity":"uncommon","id":"merriams-kangaroo-rat","subtitle":"Rodent","details":"This desert rodent of the American Southwest hops like a tiny kangaroo and can live its whole life without drinking water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Merriam%27s_Kangaroo_Rat.jpg?width=1024"},{"name":"Deer Mouse","rarity":"uncommon","id":"deer-mouse","subtitle":"Rodent","details":"Among the most widespread mice in North America, this big-eared climber nests in trees, burrows and logs from Canada to Mexico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Deer_Mouse_%28Peromyscus_maniculatus%29_%289310532204%29.jpg?width=1024"},{"name":"Norway Lemming","rarity":"uncommon","id":"norway-lemming","subtitle":"Rodent","details":"Famous for its boom-and-bust cycles, this boldly patterned Scandinavian rodent defends itself fiercely despite its tiny size.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tunturisopuli_Lemmus_Lemmus.jpg?width=1024"},{"name":"Star-nosed Mole","rarity":"uncommon","id":"star-nosed-mole","subtitle":"Small Mammal","details":"Its nose carries 22 fleshy feelers packed with touch sensors, letting this swamp mole identify food in a fraction of a second.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Condylura.jpg?width=1024"},{"name":"European Mole","rarity":"uncommon","id":"european-mole","subtitle":"Small Mammal","details":"A velvet-furred tunneller whose spade-like front paws can shift many times its own body weight in soil each day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Talpa_europaea_I.jpg?width=1024"},{"name":"Four-toed Hedgehog","rarity":"uncommon","id":"four-toed-hedgehog","subtitle":"Small Mammal","details":"The smallest African hedgehog, this nocturnal species has only four toes on its hind feet and freezes into a spiny ball.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atelerix_albiventris.jpg?width=1024"},{"name":"Agile Wallaby","rarity":"uncommon","id":"agile-wallaby","subtitle":"Marsupial","details":"The agile wallaby is the most common wallaby of northern Australia's tropical grasslands, flashing a pale cheek stripe as it bounds away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agile_Wallaby_pair_-_East_Point_Reserve.jpg?width=1024"},{"name":"Swamp Wallaby","rarity":"uncommon","id":"swamp-wallaby","subtitle":"Marsupial","details":"Unlike other wallabies, the swamp wallaby of eastern Australia can be pregnant again before its previous joey is even born.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wallabia_bicolor_Jenolan_Caves.jpg?width=1024"},{"name":"Red-necked Wallaby","rarity":"uncommon","id":"red-necked-wallaby","subtitle":"Marsupial","details":"Also called Bennett's wallaby, this Tasmanian and mainland Australian grazer has even established wild populations in Britain and New Zealand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macropus_rufogriseus_rufogriseus_Bruny.jpg?width=1024"},{"name":"Common Brushtail Possum","rarity":"uncommon","id":"common-brushtail-possum","subtitle":"Marsupial","details":"Australia's most familiar possum, the brushtail spends its nights in roofs and treetops alike, feasting on leaves, flowers and fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trichosurus_vulpecula_1.jpg?width=800"},{"name":"Greater Bilby","rarity":"uncommon","id":"greater-bilby","subtitle":"Marsupial","details":"With rabbit-long ears and a silky blue-grey coat, the greater bilby digs spiral burrows in Australia's deserts and emerges only after dark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bilby_at_Sydney_Wildlife_World.jpg?width=1024"},{"name":"Numbat","rarity":"uncommon","id":"numbat","subtitle":"Marsupial","details":"Western Australia's numbat is one of the few marsupials active by day, licking up as many as twenty thousand termites with its long tongue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Numbat%2C_Dryandra_Woodland%2C_Western_Australia.jpg?width=1024"},{"name":"Spotted-tailed Quoll","rarity":"uncommon","id":"spotted-tailed-quoll","subtitle":"Marsupial","details":"The spotted-tailed quoll is a cat-sized Australian hunter — one of the few quolls whose spots continue right down its long, white-speckled tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dasyurus_maculatus_398569942.jpg?width=1024"},{"name":"Matschie's Tree-kangaroo","rarity":"uncommon","id":"matschies-tree-kangaroo","subtitle":"Marsupial","details":"Matschie's tree-kangaroo climbs through the cloud forests of New Guinea's Huon Peninsula, balancing with a tail as long as its body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dendrolagus_matschiei_at_the_Bronx_Zoo_007.jpg?width=800"},{"name":"Rock Hyrax","rarity":"uncommon","id":"rock-hyrax","subtitle":"Oddball","details":"The rock hyrax may look like a guinea pig, but its closest living relatives are elephants — a kinship shown in its tiny tusk-like teeth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rock_hyrax_Serengeti_National_Park.jpg?width=1024"},{"name":"Giant Pangolin","rarity":"uncommon","id":"giant-pangolin","subtitle":"Oddball","details":"The giant pangolin is the largest of the eight pangolin species, an African giant that can stretch over two metres counting its heavy scaled tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Em%20-%20Smutsia%20gigantea%20-%202.jpg?width=1024"},{"name":"Chinese Pangolin","rarity":"uncommon","id":"chinese-pangolin","subtitle":"Oddball","details":"The Chinese pangolin digs burrows so deep and roomy that other animals move in after it leaves; it carries its single pup riding on its tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manis_pentadactyla_%2829054818144%29.jpg?width=1024"},{"name":"Western Long-beaked Echidna","rarity":"uncommon","id":"western-long-beaked-echidna","subtitle":"Oddball","details":"New Guinea's western long-beaked echidna probes the forest floor with its down-curved bill, hunting earthworms, and like all echidnas, lays eggs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long-beakedEchidna.jpg?width=1024"},{"name":"Big Brown Bat","rarity":"uncommon","id":"big-brown-bat","subtitle":"Bat","details":"A hardy North American bat that roosts in barns and attics, echolocating to catch beetles and other night-flying insects over fields and yards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Big_brown_bat_crawl.png?width=500"},{"name":"Mexican Free-tailed Bat","rarity":"uncommon","id":"mexican-free-tailed-bat","subtitle":"Bat","details":"A fast-flying American bat famous for its vast cave colonies; streams of millions pour out at dusk to hunt insects over farms and deserts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mexican_free-tailed_bat_%288006856842%29.jpg?width=1024"},{"name":"Eastern Red Bat","rarity":"uncommon","id":"eastern-red-bat","subtitle":"Bat","details":"A rusty-red North American bat that roosts alone in tree leaves, camouflaged as a dead leaf, and migrates south as winter cold sets in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/C-red-bat.jpg?width=1024"},{"name":"Hoary Bat","rarity":"uncommon","id":"hoary-bat","subtitle":"Bat","details":"A frost-tipped, tree-roosting bat found from Canada to South America, one of the widest-ranging of all bats, migrating long distances yearly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoary_bat_Lasiurus_cinereus_%28cropped%29.jpg?width=1024"},{"name":"Pallid Bat","rarity":"uncommon","id":"pallid-bat","subtitle":"Bat","details":"A pale desert bat of western North America that lands on the ground to hunt scorpions, centipedes and crickets, listening with its big ears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pallid_Bat_%28Antrozous_pallidus%29.jpg?width=1024"},{"name":"Greater Bulldog Bat","rarity":"uncommon","id":"greater-bulldog-bat","subtitle":"Bat","details":"A large fishing bat of the American tropics that trawls rivers and lagoons with hooked claws, snatching small fish from the water's surface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Captive_Noctilio_leporinus.jpg?width=1024"},{"name":"Side-striped Jackal","rarity":"common","id":"side-striped-jackal","subtitle":"Carnivore","details":"The side-striped jackal, paler and shyer than its black-backed cousin, forages in African woodlands for fruit and small prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lupulella_adusta_in_Kalabo_Zambia_01.jpeg?width=1024"},{"name":"African Golden Wolf","rarity":"common","id":"african-golden-wolf","subtitle":"Carnivore","details":"The African golden wolf, once thought a jackal, is a true wolf relative hunting small prey across North and East Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African_wolf%2C_Dagana%2C_Senegal.jpg?width=1024"},{"name":"Bush Dog","rarity":"common","id":"bush-dog","subtitle":"Carnivore","details":"The bush dog is a small, web-toed South American canid that hunts pacas in packs near Amazonian waterways.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Speothos_venaticus_Zoo_Praha_2011-5_%28cropped%29.jpg?width=1024"},{"name":"Smooth-coated Otter","rarity":"common","id":"smooth-coated-otter","subtitle":"Carnivore","details":"The smooth-coated otter, Asia's largest otter, fishes cooperatively in family groups in rivers and reservoirs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Smooth-coated_otter_%28Lutrogale_perspicillata%29_Kota_Kinabatangan.jpg?width=1024"},{"name":"Hoary Fox","rarity":"common","id":"hoary-fox","subtitle":"Carnivore","details":"The hoary fox is a small Brazilian canid that specializes in termites and insects in the cerrado grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lycalopex_vetulus_in_Bacury_Lodge%2C_Anhembi_5.jpg?width=1024"},{"name":"Sechuran Fox","rarity":"common","id":"sechuran-fox","subtitle":"Carnivore","details":"The Sechuran fox is the smallest South American fox, foraging in Peru and Ecuador's coastal Sechura Desert.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zorro_costero_%28cropped%29.jpg?width=1024"},{"name":"Pampas Fox","rarity":"common","id":"pampas-fox","subtitle":"Carnivore","details":"The pampas fox ranges across southern South America's grasslands, an opportunistic hunter of rodents, hares and fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Na_estrada%3F.jpg?width=1024"},{"name":"Island Fox","rarity":"common","id":"island-fox","subtitle":"Carnivore","details":"The island fox lives only on California's Channel Islands, where each island's foxes form a distinct subspecies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Urocyon_littoralis_%28Island_fox%29_FWS_001.jpg?width=1024"},{"name":"Corsac Fox","rarity":"common","id":"corsac-fox","subtitle":"Carnivore","details":"The corsac fox roams Central Asian steppes, sheltering in marmot burrows and hunting rodents in small packs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_corsac.jpg?width=1024"},{"name":"Bengal Fox","rarity":"common","id":"bengal-fox","subtitle":"Carnivore","details":"The Bengal fox is a slender fox of Indian grasslands and scrub, recognizable by its black-tipped, bushy tail and large ears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bengal_Fox_-_Shreeram_M_V_-_Rajasthan%2C_India.jpg?width=1024"},{"name":"Blanford's Fox","rarity":"common","id":"blanfords-fox","subtitle":"Carnivore","details":"Blanford's fox is a tiny, huge-eared fox of Middle Eastern and Central Asian rocky deserts, hunting insects at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blandford%27s_fox_1.jpg?width=1024"},{"name":"Ruppell's Fox","rarity":"common","id":"ruppells-fox","subtitle":"Carnivore","details":"Rüppell's fox is a pale sand fox of North African and Middle Eastern deserts, with furred soles for walking on hot sand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/R%C3%BCppell%27s_fox.jpg?width=1024"},{"name":"Pale Fox","rarity":"common","id":"pale-fox","subtitle":"Carnivore","details":"The pale fox is a sand-colored Sahel fox of Africa, one of the least-known canids, sheltering in burrow systems by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pale%20fox%20%28Vulpes%20pallida%29.jpg?width=1024"},{"name":"Tibetan Fox","rarity":"common","id":"tibetan-fox","subtitle":"Carnivore","details":"The Tibetan fox, with its famously square face and thick coat, hunts plateau pikas on the high, windswept Tibetan Plateau.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_ferrilata.jpg?width=1024"},{"name":"Marbled Cat","rarity":"common","id":"marbled-cat","subtitle":"Carnivore","details":"The marbled cat is a tree-climbing small cat of Southeast Asian forests with a cloud-patterned coat and very long tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marbled_cat_borneo.jpg?width=1024"},{"name":"Leopard Cat","rarity":"common","id":"leopard-cat","subtitle":"Carnivore","details":"The leopard cat is a widespread small spotted cat of Asia, about house-cat size, that readily swims and hunts near water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prionailurus_bengalensis_bengalensis_2-D%C3%A9coupe.JPG?width=1024"},{"name":"Jungle Cat","rarity":"common","id":"jungle-cat","subtitle":"Carnivore","details":"The jungle cat, despite its name, hunts rodents and birds in wetlands and grasslands from Egypt to Southeast Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FelisChausMunsiari1.jpg?width=1024"},{"name":"Sand Cat","rarity":"common","id":"sand-cat","subtitle":"Carnivore","details":"The sand cat hunts rodents in true deserts of Africa and Asia, with furred foot pads and ears set low and wide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Persian_sand_CAT.jpg?width=1024"},{"name":"Black-footed Cat","rarity":"common","id":"black-footed-cat","subtitle":"Carnivore","details":"The black-footed cat, Africa's smallest cat, is a relentless nocturnal hunter of rodents and birds in dry grassland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zoo_Wuppertal_Schwarzfusskatze.jpg?width=1024"},{"name":"Pallas's Cat","rarity":"common","id":"pallass-cat","subtitle":"Carnivore","details":"Pallas's cat, or manul, is a fluffy, flat-faced cat of Central Asian steppes with round pupils unusual among small cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manoel.jpg?width=1024"},{"name":"African Wildcat","rarity":"common","id":"african-wildcat","subtitle":"Carnivore","details":"The African wildcat, ancestor of the house cat, is a tabby-like hunter of rodents across Africa and the Middle East.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_African_Wildcat_%28Felis_sylvestris_cafra%29_female_..._%28captive_specimen%29_%2839789072173%29.jpg?width=1024"},{"name":"European Wildcat","rarity":"common","id":"european-wildcat","subtitle":"Carnivore","details":"The European wildcat is a robust, thick-tailed forest cat, distinct from tabbies by its blunt, ringed tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Felis_silvestris_silvestris_Luc_Viatour.jpg?width=800"},{"name":"Margay","rarity":"common","id":"margay","subtitle":"Carnivore","details":"The margay is a rainforest cat that can rotate its hind ankles 180 degrees to climb headfirst down tree trunks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Margay_in_Costa_Rica.jpg?width=1024"},{"name":"Geoffroy's Cat","rarity":"common","id":"geoffroys-cat","subtitle":"Carnivore","details":"Geoffroy's cat is a small spotted cat of southern South America that often stands on its hind legs to scan for prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salzkatze.jpg?width=1024"},{"name":"Oncilla","rarity":"common","id":"oncilla","subtitle":"Carnivore","details":"The oncilla, or little spotted cat, is a tiny nocturnal forest cat of Central and South America, adept at climbing and swimming.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snethlage%27s_Tigrina_imported_from_iNaturalist_photo_354017009_on_2_August_2024_%28cropped%29.jpg?width=1024"},{"name":"Pampas Cat","rarity":"common","id":"pampas-cat","subtitle":"Carnivore","details":"The pampas cat is a stocky small cat of South American high grasslands, variable in coat from gray to rusty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leopardus%20pajeros%2098472372.jpg?width=1024"},{"name":"Rusty-spotted Cat","rarity":"common","id":"rusty-spotted-cat","subtitle":"Carnivore","details":"The rusty-spotted cat of India and Sri Lanka is one of the world's smallest wild cats, weighing barely a kilogram.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rusty_spotted_cat_1.jpg?width=1024"},{"name":"African Golden Cat","rarity":"common","id":"african-golden-cat","subtitle":"Carnivore","details":"The African golden cat is a secretive rainforest cat, variable in color from red-gold to dark gray, found across equatorial Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caracal%20aurata%20Tanzania.png?width=500"},{"name":"Least Weasel","rarity":"common","id":"least-weasel","subtitle":"Carnivore","details":"The least weasel is the world's smallest carnivore, able to chase mice and voles through their own tunnels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mustela_nivalis_-British_Wildlife_Centre-4.jpg?width=1024"},{"name":"Marbled Polecat","rarity":"common","id":"marbled-polecat","subtitle":"Carnivore","details":"The marbled polecat is a boldly blotched weasel of Eurasian steppes that does a handstand display when threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marbled_polecat.jpg?width=1024"},{"name":"Striped Polecat","rarity":"common","id":"striped-polecat","subtitle":"Carnivore","details":"The striped polecat, or zorilla, is a skunk-like African mustelid that sprays musk and wears warning stripes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African_polecat_walking_in_leaves_-_DPLA_-_fa39b9e9bcf1097e237ba8b92922c4eb.jpg?width=1024"},{"name":"Yellow Mongoose","rarity":"common","id":"yellow-mongoose","subtitle":"Carnivore","details":"The yellow mongoose lives in family burrows in southern African grasslands, often sharing warrens with meerkats and ground squirrels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/082_Yellow_mongoose_in_Khomas_Region_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Common Dwarf Mongoose","rarity":"common","id":"common-dwarf-mongoose","subtitle":"Carnivore","details":"The common dwarf mongoose, Africa's smallest carnivore, forages in packs that post sentries against hawks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dwarf_Mongoose_%28Helogale_parvula%29_%286002158282%29.jpg?width=1024"},{"name":"Indian Grey Mongoose","rarity":"common","id":"indian-grey-mongoose","subtitle":"Carnivore","details":"The Indian grey mongoose is famed for lightning-fast battles with cobras and other snakes across the Indian subcontinent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Herpestes_edwardsii_at_Hyderaba.jpg?width=1024"},{"name":"Yellow Baboon","rarity":"common","id":"yellow-baboon","subtitle":"Primate","details":"Named for its yellowish-brown coat, this East African savanna baboon lives in large troops that forage widely for grass, seeds and fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papio_cynocephalus02.jpg?width=1024"},{"name":"Chacma Baboon","rarity":"common","id":"chacma-baboon","subtitle":"Primate","details":"Southern Africa's chacma is among the largest baboons; troops roam from Cape shores to mountain slopes under a dominant male's watch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chacma_Baboon_%28Papio_ursinus%29_%2816824823063%29.jpg?width=1024"},{"name":"Guinea Baboon","rarity":"common","id":"guinea-baboon","subtitle":"Primate","details":"West Africa's smallest baboon, the reddish Guinea kind lives in unusually relaxed, friendly multi-male troops along wooded savannas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male_Guinea_Baboon_in_Nuremberg_Zoo.jpg?width=1024"},{"name":"Drill","rarity":"common","id":"drill","subtitle":"Primate","details":"Cameroon and Nigeria's drill is a shy forest baboon cousin: males wear a black face framed in white, with a rainbow-hued rump.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Drill%20%28Mandrillus%20leucophaeus%29.jpg?width=1024"},{"name":"Southern Pig-tailed Macaque","rarity":"common","id":"southern-pig-tailed-macaque","subtitle":"Primate","details":"Named for its short, curled pig-like tail, this stocky macaque of Malaya and Sumatra forages on the forest floor more than most relatives.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_Pig-tailed_Macaque_-_Shreeram_MV.jpg?width=1024"},{"name":"Formosan Rock Macaque","rarity":"common","id":"formosan-rock-macaque","subtitle":"Primate","details":"Taiwan's only native monkey lives in rocky coastal hills and mountain forests, its cheeks pouched with seeds and fruit for later.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Taiwanese_macaque_%28Macaca_cyclopis%29_female_Yangmingshan_2.jpg?width=1024"},{"name":"Toque Macaque","rarity":"common","id":"toque-macaque","subtitle":"Primate","details":"Sri Lanka's toque macaque wears a whorl of crown hair like a brimless cap and raids fruit trees in troops led by older females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macaca_sinica_-_01.jpg?width=1024"},{"name":"Bonnet Macaque","rarity":"common","id":"bonnet-macaque","subtitle":"Primate","details":"Southern India's bonnet macaque takes its name from the cap of long hair radiating from the crown of its head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bonnet%20macaque%20%28Macaca%20radiata%29%202.jpg?width=1024"},{"name":"Northern White-cheeked Gibbon","rarity":"common","id":"northern-white-cheeked-gibbon","subtitle":"Primate","details":"Vietnam and Laos' gibbons change colour with age: black males keep their white cheeks, while females turn golden-buff as adults.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Witwanggibbon_M.jpg?width=1024"},{"name":"Pileated Gibbon","rarity":"common","id":"pileated-gibbon","subtitle":"Primate","details":"Thailand and Cambodia's pileated gibbon swings through evergreen forest, the male jet black and the female silver-grey with a black cap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/At_the_Psychiatrist_%282926544583%29.jpg?width=1024"},{"name":"Muller's Gibbon","rarity":"common","id":"mullers-gibbon","subtitle":"Primate","details":"Borneo's grey gibbon greets dawn with bubbling calls from family territories, swinging through dipterocarp forest in pairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/M%C3%BCller%27s_Gibbon_0A2A2463.jpg?width=1024"},{"name":"Venezuelan Red Howler Monkey","rarity":"common","id":"venezuelan-red-howler-monkey","subtitle":"Primate","details":"Deep red and deeply loud, this howler of Venezuela and Colombia's llanos and forests feeds mostly on leaves from the high canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alouatta%20arctoidea%20%28Ursine%20howler%20monkey%29.jpg?width=1024"},{"name":"Black Howler Monkey","rarity":"common","id":"black-howler-monkey","subtitle":"Primate","details":"Males are black and females golden-brown in this slow, leaf-eating howler whose roars roll across Central and South American forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_Howler_Monkey_%28adult_male%29_4.jpg?width=1024"},{"name":"Brown Spider Monkey","rarity":"common","id":"brown-spider-monkey","subtitle":"Primate","details":"Colombia and Venezuela's brown spider monkey travels fast through high canopy, its long tail curling around branches like a rope.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BrownSpiderMonkey_%28edit2%29.jpg?width=1024"},{"name":"Red-faced Spider Monkey","rarity":"common","id":"red-faced-spider-monkey","subtitle":"Primate","details":"Guianas and Brazil's red-faced spider monkey shows bare crimson skin on its face and swings through rainforest in fission-fusion parties.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ateles%20paniscus%20by%20Kitty%20Terwolbeck.jpg?width=1024"},{"name":"Pied Tamarin","rarity":"common","id":"pied-tamarin","subtitle":"Primate","details":"Around Manaus in Brazil, the pied tamarin's naked face stays bare and dark while its body wears a white front and brown back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saguinus_bicolor_Parque_do_Mindu.jpg?width=1024"},{"name":"Geoffroy's Tamarin","rarity":"common","id":"geoffroys-tamarin","subtitle":"Primate","details":"Panama and Colombia's smallest monkey sports a white wedge on its nape and races along branches in family groups of up to nine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Geoffroy%27s_tamarin_%28Saguinus_geoffroyi%29_2.jpg?width=1024"},{"name":"Black-tufted Marmoset","rarity":"common","id":"black-tufted-marmoset","subtitle":"Primate","details":"Central Brazil's black-tufted marmoset wears dramatic black ear brushes and thrives from forest edge to city parks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black-tufted_marmoset_%28sagui-de-tufos-pretos%29.jpg?width=1024"},{"name":"Goeldi's Monkey","rarity":"common","id":"goeldis-monkey","subtitle":"Primate","details":"A rare, dark little monkey of the western Amazon, Goeldi's kind was described in 1904 and leaps between low branches in small groups.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Springtamarin_%28Callimico_goeldii%29.jpg?width=800"},{"name":"Three-striped Night Monkey","rarity":"common","id":"three-striped-night-monkey","subtitle":"Primate","details":"The only truly nocturnal monkeys, night monkeys peer from Amazon tree holes at dusk with huge brown eyes, calling softly to mates.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aotus%20trivirgatus.jpg?width=1024"},{"name":"White-faced Saki","rarity":"common","id":"white-faced-saki","subtitle":"Primate","details":"Amazon sakis wear contrasting faces: males black with a white mask, females grey-flecked, both leaping powerfully between trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pithecia%20pithecia.jpg?width=1024"},{"name":"Mule Deer","rarity":"common","id":"mule-deer","subtitle":"Hoofed Mammal","details":"Named for its large, mule-like ears, this western North American deer bounds away from danger with all four feet leaving the ground together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mule_buck_elk_creek_m_myatt_%285489214303%29.jpg?width=1024"},{"name":"Sika Deer","rarity":"common","id":"sika-deer","subtitle":"Hoofed Mammal","details":"A spotted deer of East Asian forests, the sika keeps its spots as an adult, and stags make eerie whistling calls during the autumn rut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cervus_nippon_002.jpg?width=1024"},{"name":"Roe Deer","rarity":"common","id":"roe-deer","subtitle":"Hoofed Mammal","details":"A small, graceful deer of European woodlands, the roe buck's short antlers have just three points, and fawns lie hidden in grass while mothers feed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roe_deer_%28Capreolus_capreolus%29_young_male_Cumnor.jpg?width=1024"},{"name":"Sambar","rarity":"common","id":"sambar","subtitle":"Hoofed Mammal","details":"One of Asia's largest deer, the sambar is a strong swimmer that forages at night in forests from India to Indonesia, stalked by tigers and dholes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sambar_%28Cervus_unicolor_unicolor%29_male.jpg?width=1024"},{"name":"Reeves's Muntjac","rarity":"common","id":"reevess-muntjac","subtitle":"Hoofed Mammal","details":"A tiny barking deer: this small muntjac of China gives sharp bark-like alarm calls and has been introduced to parks and woodlands in England.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinesischer_Muntjak_Muntiacus_reevesi_Zoo_Augsburg-04.jpg?width=1024"},{"name":"Chinese Water Deer","rarity":"common","id":"chinese-water-deer","subtitle":"Hoofed Mammal","details":"A small deer with no antlers at all — instead, males grow long, curved canine 'fangs', and this marsh deer swims readily between reedbeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hydropotes_inermis_male.JPG?width=1024"},{"name":"Southern Pudu","rarity":"common","id":"southern-pudu","subtitle":"Hoofed Mammal","details":"One of the world's smallest deer, barely 40 centimetres tall, the pudu hides in the dense bamboo undergrowth of Chilean and Argentine forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_pudu_%28Pudu_puda%29_male_Chiloe.jpg?width=1024"},{"name":"Marsh Deer","rarity":"common","id":"marsh-deer","subtitle":"Hoofed Mammal","details":"South America's largest deer wades through Pantanal wetlands on long legs and splayed hooves, feeding on aquatic plants in flooded grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cervo_do_pantano.jpg?width=800"},{"name":"Pampas Deer","rarity":"common","id":"pampas-deer","subtitle":"Hoofed Mammal","details":"A deer of South American grasslands, the pampas deer once shared the plains with gauchos' cattle in huge numbers, grazing open country in small herds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/O._bezoarticus_buck.jpg?width=1024"},{"name":"Barasingha","rarity":"common","id":"barasingha","subtitle":"Hoofed Mammal","details":"The swamp deer of India is named for its many-tined antlers — 'bara singha' means twelve horns — and it wades through tall, wet grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Swamp_deer_%28Indian_Barahshinga%29.gif?width=1024"},{"name":"Eld's Deer","rarity":"common","id":"elds-deer","subtitle":"Hoofed Mammal","details":"A graceful deer of Southeast Asian floodplains, Eld's deer has lyre-shaped antlers and spreads its hooves to walk across marshy ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panolia_eldii_thamin.jpg?width=1024"},{"name":"Grant's Gazelle","rarity":"common","id":"grants-gazelle","subtitle":"Hoofed Mammal","details":"A tall, hardy gazelle of East African plains, Grant's gazelle tolerates heat and drought that drive other antelope to seek shade and water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ngorongoro_Grant-Gazelle.jpg?width=1024"},{"name":"Kirk's Dik-dik","rarity":"common","id":"kirks-dik-dik","subtitle":"Hoofed Mammal","details":"A tiny antelope standing just 40 centimetres tall, the dik-dik is named for the female's alarm whistle and marks its territory with scent glands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Madoqua_kirkii_-_male_%28Namutoni%29.jpg?width=1024"},{"name":"Steenbok","rarity":"common","id":"steenbok","subtitle":"Hoofed Mammal","details":"A small, solitary antelope of southern Africa, the steenbok can survive without free water and digs up bulbs and roots in dry country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raphicerus_campestris_male_%28Etosha%2C_2012%29.jpg?width=1024"},{"name":"Klipspringer","rarity":"common","id":"klipspringer","subtitle":"Hoofed Mammal","details":"This 'rock jumper' walks on the tips of its hooves like a ballerina, bounding between boulders in rocky African hills in lifelong pairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maasai_klipspringer_%28Oreotragus_oreotragus_schillingsi%29_male_Serengeti.jpg?width=1024"},{"name":"Common Duiker","rarity":"common","id":"common-duiker","subtitle":"Hoofed Mammal","details":"A small antelope named from the Afrikaans for 'diver', for its habit of diving into bushes when alarmed, it browses across most of Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9phalophe_de_grimm%2C_crop.jpg?width=1024"},{"name":"Lesser Kudu","rarity":"common","id":"lesser-kudu","subtitle":"Hoofed Mammal","details":"A shy, striped antelope of East African bush, the lesser kudu is smaller than its greater cousin but the bulls' spiral horns are just as elegant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lesser_Kudu_Male_%28Tragelaphus_imberbis%29.jpg?width=1024"},{"name":"Black Wildebeest","rarity":"common","id":"black-wildebeest","subtitle":"Hoofed Mammal","details":"The white-tailed gnu of South African plains, this wildebeest has a dark coat, white tail and horns that curve forward like hooks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_Wildebeest_%28Connochaetes_gnou%29_%2831746882054%29.jpg?width=1024"},{"name":"Hartebeest","rarity":"common","id":"hartebeest","subtitle":"Hoofed Mammal","details":"A long-faced antelope built for endurance, the hartebeest can sustain high speeds over long distances across African grasslands and floodplains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coke%27s_Hartebeest.jpg?width=1024"},{"name":"Blesbok","rarity":"common","id":"blesbok","subtitle":"Hoofed Mammal","details":"Named for the white 'blaze' down its face, the blesbok is a richly coloured antelope of South African grasslands, once roaming in great herds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blesbok%2C_Damaliscus_pygargus_phillipsi%2C_at_Krugersdorp_Game_Reserve%2C_Gauteng%2C_South_Africa_%2826872993194%29.jpg?width=1024"},{"name":"Lechwe","rarity":"common","id":"lechwe","subtitle":"Hoofed Mammal","details":"A water-loving antelope of African floodplains, the lechwe wades belly-deep to graze, its long hind legs and splayed hooves built for marshes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red_lechwe_%28Kobus_leche_leche%29_male.jpg?width=1024"},{"name":"Kob","rarity":"common","id":"kob","subtitle":"Hoofed Mammal","details":"A sturdy antelope of West and Central African floodplains, kob gather in traditional mating arenas where males display to visiting females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male_Ugandan_kob_-_Queen_Elizabeth_National_Park%2C_Uganda_%284%29.jpg?width=1024"},{"name":"Mountain Reedbuck","rarity":"common","id":"mountain-reedbuck","subtitle":"Hoofed Mammal","details":"A small, woolly antelope of rocky African hillsides, the mountain reedbuck rests in shade on hot days and whistles sharply when alarmed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_Mountain_Reedbuck_%28Redunca_fulvorufula%29_%2833043612376%29.jpg?width=800"},{"name":"Saiga Antelope","rarity":"common","id":"saiga-antelope","subtitle":"Hoofed Mammal","details":"The saiga's huge, swollen nose filters dusty air and warms freezing breath on the Central Asian steppe, where herds once numbered in millions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saiga_antelope_at_the_Stepnoi_Sanctuary.jpg?width=1024"},{"name":"Dall Sheep","rarity":"common","id":"dall-sheep","subtitle":"Hoofed Mammal","details":"A white wild sheep of Alaska and northern Canada, Dall sheep rams grow heavy curled horns and spend summers on high alpine ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dall_Sheep_male.jpg?width=1024"},{"name":"Mouflon","rarity":"common","id":"mouflon","subtitle":"Hoofed Mammal","details":"A wild sheep of Corsica and Sardinia considered an ancestor of domestic sheep, the mouflon ram carries thick, curved horns and a dark saddle patch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cyprus_mouflon_%28Ovis_gmelini_ophion%29.jpg?width=800"},{"name":"Nubian Ibex","rarity":"common","id":"nubian-ibex","subtitle":"Hoofed Mammal","details":"A desert ibex of North African and Arabian cliffs, the Nubian ibex thrives in barren mountains, descending to rare waterholes to drink.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PikiWiki_Israel_38769_Male_Ibex.jpg?width=1024"},{"name":"Himalayan Tahr","rarity":"common","id":"himalayan-tahr","subtitle":"Hoofed Mammal","details":"A shaggy wild goat of the Himalayas, the tahr's long winter mane and sure footing suit cliffs from Afghanistan to Bhutan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Himalayan_Tahr_at_Sagarmatha_National_Park%2C_Nepal_01.jpg?width=1024"},{"name":"Giant Forest Hog","rarity":"common","id":"giant-forest-hog","subtitle":"Hoofed Mammal","details":"The world's largest wild pig, this shaggy hog of African forests was unknown to science until 1904 and forages in family herds at forest edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hylochoerus_meinertzhageni2.jpg?width=1024"},{"name":"Bushpig","rarity":"common","id":"bushpig","subtitle":"Hoofed Mammal","details":"A nocturnal pig of African forests and thickets, the bushpig has a long head, tufted ears and a mane it raises when alarmed or displaying.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southern_Bush_Pig.jpg?width=1024"},{"name":"White-lipped Peccary","rarity":"common","id":"white-lipped-peccary","subtitle":"Hoofed Mammal","details":"Travelling in herds that can number in the hundreds, these peccaries roam Central and South American forests, clicking their teeth when alarmed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White-lipped_peccary_%28Tayassu_pecari%29_Rio_Negro.jpg?width=1024"},{"name":"Onager","rarity":"common","id":"onager","subtitle":"Hoofed Mammal","details":"A swift wild ass of Asian deserts, the onager can run at 70 kilometres an hour and survives on coarse grasses where water is scarce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rostov-on-Don_Zoo_Persian_onager_IMG_5268_1725.jpg?width=1024"},{"name":"Kiang","rarity":"common","id":"kiang","subtitle":"Hoofed Mammal","details":"The largest wild ass, the kiang roams the Tibetan Plateau at altitudes up to 5,000 metres, its rich chestnut coat darkening in winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kiang_-_Gunjan_Pandey.jpg?width=1024"},{"name":"African Wild Ass","rarity":"common","id":"african-wild-ass","subtitle":"Hoofed Mammal","details":"Ancestor of the domestic donkey, this pale, striped-legged wild ass survives in the rocky deserts of the Horn of Africa on little water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Equus_africanus_somaliensis_-_R%C3%A9serve_africaine_de_Sigean_01.jpg?width=1024"},{"name":"Least Chipmunk","rarity":"common","id":"least-chipmunk","subtitle":"Rodent","details":"The smallest chipmunk, this bright-striped species ranges across North American forests and sagebrush, pouching seeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tamias_minimus.jpg?width=1024"},{"name":"Siberian Chipmunk","rarity":"common","id":"siberian-chipmunk","subtitle":"Rodent","details":"The only chipmunk native outside North America, this striped burrower hoards seeds in underground chambers across northern Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Streifenhoernchen.jpg?width=1024"},{"name":"California Ground Squirrel","rarity":"common","id":"california-ground-squirrel","subtitle":"Rodent","details":"A speckled burrower of western meadows, it stands sentry on rocks and boulders, whistling alarms when hawks approach.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CA_Ground_Squirrel_on_rock.jpg?width=1024"},{"name":"Rock Squirrel","rarity":"common","id":"rock-squirrel","subtitle":"Rodent","details":"One of the largest ground squirrels, this rock-dwelling southwestern species climbs well and sunbathes on boulders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spermophilus_variegatus.jpg?width=800"},{"name":"Harris's Antelope Squirrel","rarity":"common","id":"harriss-antelope-squirrel","subtitle":"Rodent","details":"This desert ground squirrel shades itself with its curled tail like a parasol and sprawls on cool ground to shed heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ammospermophilus_harrisii2.jpg?width=1024"},{"name":"Douglas Squirrel","rarity":"common","id":"douglas-squirrel","subtitle":"Rodent","details":"A noisy, energetic conifer-forest squirrel of the Pacific Northwest, it harvests whole cones and caches them in middens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Douglas_Squirrel_DSC3742vvc.jpg?width=1024"},{"name":"Himalayan Marmot","rarity":"common","id":"himalayan-marmot","subtitle":"Rodent","details":"One of the highest-living mammals, this large marmot whistles alarms across Himalayan meadows and hibernates most of the year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Himalayan_Marmot_at_Tshophu_Lake_Bhutan_091007_b.jpg?width=1024"},{"name":"Bobak Marmot","rarity":"common","id":"bobak-marmot","subtitle":"Rodent","details":"A stocky steppe marmot of Central Asia whose family colonies dig burrows used for generations, topped with lookout mounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marmotte-bobak.png?width=500"},{"name":"Bank Vole","rarity":"common","id":"bank-vole","subtitle":"Rodent","details":"A small reddish-brown vole of European woodlands that climbs shrubs for berries and stores seeds in its burrow for winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bank_vole_%28Clethrionomys_glareolus%29_Drenthe.jpg?width=1024"},{"name":"Field Vole","rarity":"common","id":"field-vole","subtitle":"Rodent","details":"A short-tailed grassland vole of Europe that threads runways through dense grass and lines its nest with shredded leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Microtus%20agrestis%2001%20by-dpc.jpg?width=1024"},{"name":"European Water Vole","rarity":"common","id":"european-water-vole","subtitle":"Rodent","details":"Larger than other voles, this semi-aquatic rodent burrows into riverbanks and feeds on reeds, leaving piles of cut stems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Water_Vole_on_Boot_Hill_%285592665124%29.jpg?width=800"},{"name":"Northern Collared Lemming","rarity":"common","id":"northern-collared-lemming","subtitle":"Rodent","details":"The only rodent that turns white in winter, this Arctic lemming grows forked digging claws to tunnel through frozen ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Collared_lemming_standing_in_grass_-_DPLA_-_31b8863a7a5bd9e5bd2f73fc0565d883.jpg?width=1024"},{"name":"White-footed Mouse","rarity":"common","id":"white-footed-mouse","subtitle":"Rodent","details":"A versatile North American mouse that climbs trees, swims readily, and drums its front paws when alarmed or courting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White-footed_Mouse%2C_Cantley%2C_Quebec.jpg?width=1024"},{"name":"Eurasian Harvest Mouse","rarity":"common","id":"eurasian-harvest-mouse","subtitle":"Rodent","details":"Among Europe's smallest rodents, it weaves a spherical grass nest suspended among stems and climbs with a prehensile tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Micromysminutus1.jpg?width=1024"},{"name":"House Mouse","rarity":"common","id":"house-mouse","subtitle":"Rodent","details":"Originally a wild steppe rodent of Asia, this tiny, adaptable mouse now lives almost everywhere humans do and breeds year-round.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mouse_white_background.jpg?width=1024"},{"name":"Brown Rat","rarity":"common","id":"brown-rat","subtitle":"Rodent","details":"A powerful swimmer and burrower from northern Asia, this robust rat climbs well and thrives wherever food and shelter are found.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brown_Rat_%28Rattus_norvegicus%29.jpg?width=1024"},{"name":"Black Rat","rarity":"common","id":"black-rat","subtitle":"Rodent","details":"A slender, agile climber also called the roof rat, it nests in trees and upper buildings and leaps between branches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/House_Rat_David_Raju.jpg?width=1024"},{"name":"Eastern Woodrat","rarity":"common","id":"eastern-woodrat","subtitle":"Rodent","details":"Also called a pack rat, this North American rodent builds huge stick houses, called middens, used for generations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Key%20Largo%20woodrat%20(15610225542).jpg?width=1024"},{"name":"Plains Pocket Gopher","rarity":"common","id":"plains-pocket-gopher","subtitle":"Rodent","details":"A solitary tunneller of Great Plains soils, it carries food in fur-lined external cheek pockets and rarely comes aboveground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Geomys_bursarius.jpg?width=1024"},{"name":"Greater Egyptian Jerboa","rarity":"common","id":"greater-egyptian-jerboa","subtitle":"Rodent","details":"A desert hopper of North Africa that leaps metres at a time on long hind feet and seals its burrow against daytime heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jaculus_orientalis_Plzen_zoo_02.2011.jpg?width=1024"},{"name":"Mountain Viscacha","rarity":"common","id":"mountain-viscacha","subtitle":"Rodent","details":"A long-tailed, rabbit-like rodent that suns itself on Andean boulders and bolts into rock crevices when alarmed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bolivian_vizcacha.jpg?width=1024"},{"name":"Red-rumped Agouti","rarity":"common","id":"red-rumped-agouti","subtitle":"Rodent","details":"A Brazilian forest rodent with a chestnut-red rump that scatter-hoards seeds and can crack open hard Brazil nuts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red-rumped_Agouti_%2817380318590%29.jpg?width=1024"},{"name":"Damaraland Mole-rat","rarity":"common","id":"damaraland-mole-rat","subtitle":"Rodent","details":"A social Namibian burrower whose colonies dig with chisel-like teeth, lips closed behind the incisors to keep soil out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Damaraland_mole-rat.jpg?width=1024"},{"name":"Common Shrew","rarity":"common","id":"common-shrew","subtitle":"Small Mammal","details":"One of Europe's smallest mammals, this fiercely hungry insect-eater must eat close to its own body weight every day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sorex-araneus.jpg?width=1024"},{"name":"Etruscan Shrew","rarity":"common","id":"etruscan-shrew","subtitle":"Small Mammal","details":"Among the smallest mammals on Earth by weight, this tiny shrew's heart can beat more than 1,000 times per minute.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suncus_etruscus.jpg?width=1024"},{"name":"Long-eared Hedgehog","rarity":"common","id":"long-eared-hedgehog","subtitle":"Small Mammal","details":"A desert hedgehog of Asia whose oversized ears shed body heat and pick up the faint sounds of insects in dry grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hedgehog_cyprus_hg.jpg?width=1024"},{"name":"Meadow Vole","rarity":"common","id":"meadow-vole","subtitle":"Rodent","details":"A prolific North American grassland vole whose tunnel networks and runways thread through meadows, orchards and marshes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern_meadow_vole_%28Microtus_pennsylvanicus%29_emerging_from_a_runway_in_the_snow_in_Kennebunk%2C_Maine%2C_USA.jpg?width=1024"},{"name":"Richardson's Ground Squirrel","rarity":"common","id":"richardsons-ground-squirrel","subtitle":"Rodent","details":"A prairie ground squirrel nicknamed the flickertail for its constant tail-twitching as it stands scanning for hawks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Richardson%27s_ground_squirrel_%28Urocitellus_richardsonii%29_Calgary.jpg?width=1024"},{"name":"Western Grey Kangaroo","rarity":"common","id":"western-grey-kangaroo","subtitle":"Marsupial","details":"Western grey kangaroos rest in the shade through the heat of the Australian day, then spread out at dusk to graze in their thousands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kangaroo_Island_Western_grey_kangaroo_%28Macropus_fuliginosus_fuliginosus%29_male.jpg?width=1024"},{"name":"Common Wallaroo","rarity":"common","id":"common-wallaroo","subtitle":"Marsupial","details":"Stockier and shaggier than a kangaroo, the common wallaroo shelters among rocky hills across most of mainland Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macropus_robustus2.jpg?width=1024"},{"name":"Goodfellow's Tree-kangaroo","rarity":"common","id":"goodfellows-tree-kangaroo","subtitle":"Marsupial","details":"Goodfellow's tree-kangaroo, named for zoologist Walter Goodfellow, leaps between branches in the montane rainforests of New Guinea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tree_kangaroo2.jpg?width=1024"},{"name":"Common Ringtail Possum","rarity":"common","id":"common-ringtail-possum","subtitle":"Marsupial","details":"The common ringtail possum carries leaves home in its curled prehensile tail and builds a leafy drey, rather than using a tree hollow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Possum_Ring-tailed444.jpg?width=1024"},{"name":"Greater Glider","rarity":"common","id":"greater-glider","subtitle":"Marsupial","details":"Australia's greater glider can glide over a hundred metres between eucalypts, folding its furry membrane like a parachute to land.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Greater%20Glider%20%28Petauroides%20volans%29%20in%20a%20Eucalypt.jpg?width=1024"},{"name":"Long-nosed Bandicoot","rarity":"common","id":"long-nosed-bandicoot","subtitle":"Marsupial","details":"With its pointed snout, the long-nosed bandicoot snuffles through Sydney gardens and forests alike, leaving neat conical holes as it digs for grubs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long-nosed_Bandicoot_0059.jpg?width=1024"},{"name":"Eastern Quoll","rarity":"common","id":"eastern-quoll","subtitle":"Marsupial","details":"Once widespread on mainland Australia, the eastern quoll now survives in Tasmania, pouncing on insects and small prey in the night grasslands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern_quoll_%28Dasyurus_viverrinus%29_fawn_morph_Esk_Valley.jpg?width=1024"},{"name":"Common Opossum","rarity":"common","id":"common-opossum","subtitle":"Marsupial","details":"The common opossum ranges from Mexico to Argentina, an adaptable marsupial equally at home in rainforest, farmland and the edges of towns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rabipelao2.jpg?width=1024"},{"name":"Monito del Monte","rarity":"common","id":"monito-del-monte","subtitle":"Marsupial","details":"The monito del monte, or 'little monkey of the mountain', is a Chilean marsupial more closely related to Australian species than to opossums.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monito_del_Monte_ps6.jpg?width=1024"},{"name":"Silky Anteater","rarity":"common","id":"silky-anteater","subtitle":"Oddball","details":"The smallest anteater, the silky anteater weighs less than a can of beans and spends its life curled on branches in American tropical forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Silky_Anteater.jpg?width=1024"},{"name":"Giant Armadillo","rarity":"common","id":"giant-armadillo","subtitle":"Oddball","details":"The giant armadillo, largest of its kind, can weigh as much as an adult human and digs burrows wide enough for other animals to shelter in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Priodontes_maximus_at_R%C3%A9gina.jpg?width=1024"},{"name":"Brazilian Three-banded Armadillo","rarity":"common","id":"brazilian-three-banded-armadillo","subtitle":"Oddball","details":"One of only two armadillos that can roll into a perfect ball, this Brazilian species uses its head and tail plates to seal the sphere shut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tolypeutes%20tricinctus%20466118804.jpg?width=1024"},{"name":"Indian Pangolin","rarity":"common","id":"indian-pangolin","subtitle":"Oddball","details":"The Indian pangolin's scales are so thick that even a lion's teeth struggle to pierce them; threatened, it simply rolls into an armoured ball.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scaly_ant_eater_by_Dushy_Ranetunge_2.jpg?width=1024"},{"name":"Lowland Streaked Tenrec","rarity":"common","id":"lowland-streaked-tenrec","subtitle":"Oddball","details":"Madagascar's lowland streaked tenrec rattles special quills on its back to communicate — the only mammal known to make sound this way.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lowland_Streaked_Tenrec%2C_Mantadia%2C_Madagascar.jpg?width=1024"},{"name":"Little Brown Bat","rarity":"common","id":"little-brown-bat","subtitle":"Bat","details":"A small, long-lived North American bat that skims low over lakes and streams catching insects, navigating and hunting by echolocation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Little_Brown_Myotis_%28cropped%29.JPG?width=1024"},{"name":"Tri-colored Bat","rarity":"common","id":"tri-colored-bat","subtitle":"Bat","details":"One of North America's smallest bats, named for its three-banded hairs; it roosts in tree foliage and hibernates in caves and mines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/221205-F-KN521-0087.jpg?width=1024"},{"name":"Silver-haired Bat","rarity":"common","id":"silver-haired-bat","subtitle":"Bat","details":"A slow, low-flying forest bat whose black fur is frosted with silver tips; it roosts under loose bark and migrates south in autumn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Silver-haired_bat.JPG?width=1024"},{"name":"Townsend's Big-eared Bat","rarity":"common","id":"townsends-big-eared-bat","subtitle":"Bat","details":"A western North American bat with enormous ears nearly half its body length, which it curls like ram's horns when resting in cave roosts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Townsends_in_music_hall.jpg?width=500"},{"name":"Spotted Bat","rarity":"common","id":"spotted-bat","subtitle":"Bat","details":"A striking black-and-white desert bat of western North America whose echolocation calls are low enough for human ears to hear.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Side_view_of_spotted_bat_-Euderma_maculatum-_by_Paul_Cryan.jpg?width=1024"},{"name":"Lesser Horseshoe Bat","rarity":"common","id":"lesser-horseshoe-bat","subtitle":"Bat","details":"One of Europe's smallest bats, it wraps its wings completely around its body when hibernating in caves, cellars and old mines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bat%2820070605%29.jpg?width=1024"},{"name":"Daubenton's Bat","rarity":"common","id":"daubentons-bat","subtitle":"Bat","details":"A European 'water bat' that skims low over rivers and ponds at dusk, using its large feet to trawl insects from the surface film.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Myotis_daubentoni01.jpg?width=1024"},{"name":"Common Noctule","rarity":"common","id":"common-noctule","subtitle":"Bat","details":"A large, fast European bat that emerges before sunset to hunt beetles high over woodland and rivers, migrating long distances seasonally.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nyctalus_noctula.jpg?width=1024"},{"name":"Common Pipistrelle","rarity":"common","id":"common-pipistrelle","subtitle":"Bat","details":"A tiny European bat, weighing less than a coin, that flits erratically around gardens and street lamps snapping up midges and small moths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pipistrellus_female-1.jpg?width=1024"},{"name":"Soprano Pipistrelle","rarity":"common","id":"soprano-pipistrelle","subtitle":"Bat","details":"A small European bat told apart from its common cousin by its higher-pitched echolocation calls, favouring wetlands and river valleys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pipistrellus_pygmaeus01.jpg?width=1024"},{"name":"Brown Long-eared Bat","rarity":"common","id":"brown-long-eared-bat","subtitle":"Bat","details":"A quiet European 'whispering bat' with huge ears, which gleans moths and spiders from leaves and often listens for prey instead of echoing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plecotus_auritus_2013-2_%28cropped%29.jpg?width=1024"},{"name":"Western Barbastelle","rarity":"common","id":"western-barbastelle","subtitle":"Bat","details":"A European woodland bat with a pug-like face and ears that meet across its forehead, hunting moths along dark forest edges at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barbastella_barbastellus_01.jpg?width=1024"},{"name":"Kitti's Hog-nosed Bat","rarity":"common","id":"kittis-hog-nosed-bat","subtitle":"Bat","details":"Among the world's smallest bats — barely bigger than a bumblebee — this cave bat of Thailand and Myanmar hunts tiny insects at dusk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Craseonycteris_thonglongyai_414843825.jpg?width=1024"},{"name":"Proboscis Bat","rarity":"common","id":"proboscis-bat","subtitle":"Bat","details":"A tiny bat of Central and South American riverbanks that roosts in neat vertical lines on tree trunks, camouflaged against the bark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhynchonycteris_naso2.jpg?width=1024"},{"name":"Tent-making Bat","rarity":"common","id":"tent-making-bat","subtitle":"Bat","details":"A small fruit-eating bat of American rainforests that bites leaf ribs so the blade folds into a tent, sheltering its small colony beneath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common_tent-making_bats.JPG?width=1024"},{"name":"Yellow-winged Bat","rarity":"common","id":"yellow-winged-bat","subtitle":"Bat","details":"An African false vampire bat with bright yellow-orange wings and ears, which hangs in acacia trees and ambushes insects and scorpions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yellow-Winged_Bat.jpeg?width=1024"},{"name":"Mauritian Flying Fox","rarity":"common","id":"mauritian-flying-fox","subtitle":"Bat","details":"A golden-furred fruit bat of the Mascarene Islands that roosts in native forest trees and feeds on fruit, blossom and leaves at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2012-10-27-Mauritius%20-%20Pteropus%20niger%20-%20Roussette%20-%20L2290C.JPG?width=1024"},{"name":"Ryukyu Flying Fox","rarity":"common","id":"ryukyu-flying-fox","subtitle":"Bat","details":"A large fruit bat of Japan's Ryukyu Islands that roosts in subtropical forest trees and flies between islands to feed on figs and blossom.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteropus-dasymallus-yayeyam.jpg?width=800"},{"name":"Seychelles Fruit Bat","rarity":"common","id":"seychelles-fruit-bat","subtitle":"Bat","details":"A fruit bat of the Seychelles and Comoros islands that roosts in palm trees and feeds on mangoes, figs and other soft island fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteropus%20seychellensis.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
